const input = $input.item.json;
const query = input.query || '';
const customerName = input.customer_name || 'Buyer';
const kb = input.knowledge || {};

const systemInstruction = `You are the friendly, polite, and helpful automated AI sales assistant for Sash's Shop, a small Philippine business selling authentic SEVENTEEN K-pop photocards and albums.

COMMUNICATION RULES:
1. Tone: Warm, polite, conversational Filipino/Taglish small business style. Use friendly markers like 'Hii po! 💗', 'po/opo', 'salamat po'.
2. Language matching: Match the customer's language (natural Taglish if customer uses Taglish/Filipino, English if in English).
3. Absolute Grounding: You must ONLY state prices, stock, condition notes, shipping rates, and payment methods from the PROVIDED KNOWLEDGE BASE. NEVER invent or assume any details.
4. Transparency: Disclose that this is an automated assistant response.
5. Reservation & Payments: Do NOT confirm orders or payments automatically. Remind the buyer that payment confirmation and reservation are finalized once the seller (Sash) verifies their payment proof.
6. Multi-Match & Ambiguity: If multiple items match, politely list the options with prices and ask clarifying questions.
7. Format: Return ONLY a valid JSON object matching the requested schema.`;

const prompt = `Customer Name: ${customerName}
Customer Message: "${query}"

KNOWLEDGE BASE CONTEXT:
- Match Status: ${kb.matchStatus || 'UNKNOWN'}
- Detected Member: ${(kb.detectedMembers || []).join(', ') || 'None'}
- Products:
${JSON.stringify(kb.products || [], null, 2)}
- Shipping Rates: ${JSON.stringify(kb.shippingRates || {})}
- Packing Fees: ${JSON.stringify(kb.packingFees || {})}
- Payment Methods: ${JSON.stringify(kb.paymentMethods || [])}
- Shop Policies: Delivery days: Monday–Wednesday only; Payment deadline: 1 week with 30% non-refundable downpayment (nrdp).

Generate a grounded JSON response with this schema:
{
  "reply_text": "friendly Taglish response text",
  "confidence": 0.95,
  "matched_products": ["list of product names"],
  "needs_human_escalation": false,
  "escalation_reason": null
}`;

return {
  query,
  customerName,
  kb,
  systemInstruction,
  prompt
};

const apiResponse = $('Call Gemini Flash-Lite API').first()?.json;
const prep = $('Prepare Gemini Prompt Context').first().json;
const kb = prep.kb || {};

// Check if Gemini succeeded
if (apiResponse && apiResponse.candidates && apiResponse.candidates[0]?.content?.parts[0]?.text) {
  try {
    const parsed = JSON.parse(apiResponse.candidates[0].content.parts[0].text);
    return {
      source: 'gemini_api',
      reply_text: parsed.reply_text,
      confidence: parsed.confidence || 0.9,
      matched_products: parsed.matched_products || [],
      needs_human_escalation: parsed.needs_human_escalation || false,
      escalation_reason: parsed.escalation_reason || null
    };
  } catch (e) {
    // Parse failed, fallback
  }
}

// Deterministic Grounded Fallback Engine
let reply = "";
let confidence = 0.85;
let escalation = false;
let reason = null;
const products = kb.products || [];

if (kb.matchStatus === 'OUT_OF_STOCK') {
  const member = (kb.detectedMembers || [])[0] || 'the item';
  reply = `Hii po! 💗 As of now, ${member} is currently out of stock po. We will announce once we have new stocks available! Salamat po sa interest! 💗 (🤖 Automated shop assistant)`;
} else if (kb.matchStatus === 'EXACT_MATCH' && products.length === 1) {
  const p = products[0];
  const noteStr = p.notes ? ` Condition note: ${p.notes}.` : '';
  reply = `Hii po! 💗 For ${p.member} - ${p.product_name}, it is ₱${p.price_php} with ${p.stock} item(s) in stock.${noteStr} Delivery days are Monday–Wednesday only via J&T. Would you like to reserve this item po? (🤖 Automated shop assistant)`;
} else if (kb.matchStatus === 'AMBIGUOUS_MATCH' && products.length > 0) {
  const listStr = products.slice(0, 4).map(p => `• ${p.member} ${p.product_name} (₱${p.price_php})`).join('\n');
  reply = `Hii po! 💗 Here are the available items matching your inquiry:\n${listStr}\nWhich one were you looking for po? (🤖 Automated shop assistant)`;
} else if (kb.isShippingInquiry) {
  reply = `Hii po! 💗 Our shipping rates via J&T (includes ₱21 voucher):\n• Luzon: Small ₱79 / Medium ₱144 / Large ₱174\n• Visayas: Small ₱74 / Medium ₱134 / Large ₱164\n• Mindanao: Small ₱54 / Medium ₱104 / Large ₱144\nPacking fee: Small ₱20, Medium ₱25, Large ₱30. Delivery days are Monday–Wednesday only po! (🤖 Automated shop assistant)`;
} else if (kb.isPaymentInquiry) {
  reply = `Hii po! 💗 We accept GCash (9976111139), Maya (9976111139), and MariBank (13296983960) under F. M. A. Payment deadline is 1 week with 30% non-refundable downpayment (nrdp) po! (🤖 Automated shop assistant)`;
} else {
  reply = `Hii po! 💗 This is Sash's automated shop assistant. We have SEVENTEEN photocards and albums in stock. You can ask for specific members, prices, shipping fees, or payment options po! (🤖 Automated shop assistant)`;
  confidence = 0.7;
}

return {
  source: 'deterministic_grounded_fallback',
  reply_text: reply,
  confidence,
  matched_products: products.map(p => `${p.member} - ${p.product_name}`),
  needs_human_escalation: escalation,
  escalation_reason: reason
};
